     7→use std::alloc::{alloc as sys_alloc, dealloc as sys_dealloc, Layout};
     8→
     9→// ── 메모리 관리 ──────────────────────────────
    10→#[no_mangle]
    11→pub extern "C" fn alloc(size: usize) -> *mut u8 {
    12→    let layout = Layout::from_size_align(size, 1).unwrap();
    13→    unsafe { sys_alloc(layout) }
    14→}
    15→
    16→#[no_mangle]
    17→pub extern "C" fn dealloc(ptr: *mut u8, size: usize) {
    18→    let layout = Layout::from_size_align(size, 1).unwrap();
    19→    unsafe { sys_dealloc(ptr, layout) }
    20→}
    21→
    22→// ── 결과 직렬화 헬퍼 ─────────────────────────
    23→// 반환 형식: [4바이트 길이(LE)] + [JSON 바이트]
    24→// JS는 읽은 뒤 dealloc(ptr, 4 + len) 호출 필요
    25→fn write_result(s: &str) -> *mut u8 {
    26→    let bytes = s.as_bytes();
    27→    let len = bytes.len();
    28→    let total = 4 + len;
    29→    // size=0 레이아웃은 UB이므로 최소 1 보장
    30→    let alloc_size = total.max(1);
    31→    let layout = Layout::from_size_align(alloc_size, 1).unwrap();
    32→    unsafe {
    33→        let ptr = sys_alloc(layout);
    34→        let len_bytes = (len as u32).to_le_bytes();
    35→        ptr.copy_from(len_bytes.as_ptr(), 4);
    36→        if len > 0 {
    37→            ptr.add(4).copy_from(bytes.as_ptr(), len);
    38→        }
    39→        ptr
    40→    }
    41→}
    42→
    43→// JS에서 dealloc 호출 시 필요한 size 계산
    44→// dealloc(ptr, result_total_size(ptr)) 으로 호출
    45→#[no_mangle]
    46→pub extern "C" fn result_total_size(ptr: *const u8) -> usize {
    47→    let len = unsafe {
    48→        let mut b = [0u8; 4];
    49→        std::ptr::copy_nonoverlapping(ptr, b.as_mut_ptr(), 4);
    50→        u32::from_le_bytes(b) as usize
    51→    };
    52→    4 + len
    53→}
    54→
    55→// ── 문자열 읽기 헬퍼 ─────────────────────────
    56→unsafe fn read_str(ptr: *const u8, len: usize) -> &'static str {
    57→    let slice = std::slice::from_raw_parts(ptr, len);
    58→    std::str::from_utf8_unchecked(slice)
    59→}
    60→
    61→// ── FV-Lang 코드 평가 ────────────────────────
    62→#[no_mangle]
    63→pub extern "C" fn eval_fv_raw(ptr: *const u8, len: usize) -> *mut u8 {
    64→    let code = unsafe { read_str(ptr, len) };
    65→    let result = run_fv(code);
    66→    write_result(&result)
    67→}
    68→
    69→// ── AST 파싱 ────────────────────────────────
    70→#[no_mangle]
    71→pub extern "C" fn parse_to_ast_raw(ptr: *const u8, len: usize) -> *mut u8 {
    72→    let code = unsafe { read_str(ptr, len) };
    73→    let ast = parse_ast(code);
    74→    write_result(&ast)
    75→}
    76→
    77→// ── 버전 문자열 (null 종료) ───────────────────
    78→#[no_mangle]
    79→pub extern "C" fn fv_version_raw() -> *const u8 {
    80→    b"FV-Lang 0.1.0 (WASM)\0".as_ptr()
    81→}
    82→
    83→// ── 토큰 배열 직렬화 (디버깅용) ──────────────
    84→#[no_mangle]
    85→pub extern "C" fn get_tokens_raw(ptr: *const u8, len: usize) -> *mut u8 {
    86→    let code = unsafe { read_str(ptr, len) };
    87→    let result = get_tokens_json(code);
    88→    write_result(&result)
    89→}
    90→
    91→/// 내부 헬퍼: 토큰 배열을 JSON 문자열로 반환
    92→/// 형식: {"success":true,"tokens":["Let","Identifier(x)",...]}
    93→///       {"success":false,"error":"..."}
    94→pub fn get_tokens_json(code: &str) -> String {
    95→    use fv_lang::lexer::Token;
    96→    let lexer = match fv_lang::Lexer::new(code) {
    97→        Ok(l) => l,
    98→        Err(e) => return format!(r#"{{"success":false,"error":{}}}"#, json_str(&e.to_string())),
    99→    };
   100→    let tokens = match lexer.tokenize() {
   101→        Ok(t) => t,
   102→        Err(e) => return format!(r#"{{"success":false,"error":{}}}"#, json_str(&e.to_string())),
   103→    };
   104→
   105→    let items: Vec<String> = tokens
   106→        .iter()
   107→        .map(|t| {
   108→            let repr = match t {
   109→                Token::Fn        => "Fn".into(),
   110→                Token::Let       => "Let".into(),
   111→                Token::If        => "If".into(),
   112→                Token::Else      => "Else".into(),
   113→                Token::Match     => "Match".into(),
   114→                Token::Return    => "Return".into(),
   115→                Token::Type      => "Type".into(),
   116→                Token::Mut       => "Mut".into(),
   117→                Token::True      => "True".into(),
   118→                Token::False     => "False".into(),
   119→                Token::Plus      => "Plus".into(),
   120→                Token::Minus     => "Minus".into(),
   121→                Token::Star      => "Star".into(),
   122→                Token::Slash     => "Slash".into(),
   123→                Token::Percent   => "Percent".into(),
   124→                Token::Assign    => "Assign".into(),
   125→                Token::Eq        => "Eq".into(),
   126→                Token::Ne        => "Ne".into(),
   127→                Token::Lt        => "Lt".into(),
   128→                Token::Le        => "Le".into(),
   129→                Token::Gt        => "Gt".into(),
   130→                Token::Ge        => "Ge".into(),
   131→                Token::And       => "And".into(),
   132→                Token::Or        => "Or".into(),
   133→                Token::Not       => "Not".into(),
   134→                Token::Arrow     => "Arrow".into(),
   135→                Token::FatArrow  => "FatArrow".into(),
   136→                Token::Pipe      => "Pipe".into(),
   137→                Token::LParen    => "LParen".into(),
   138→                Token::RParen    => "RParen".into(),
   139→                Token::LBrace    => "LBrace".into(),
   140→                Token::RBrace    => "RBrace".into(),
   141→                Token::LBracket  => "LBracket".into(),
   142→                Token::RBracket  => "RBracket".into(),
   143→                Token::Comma     => "Comma".into(),
   144→                Token::Dot       => "Dot".into(),
   145→                Token::Colon     => "Colon".into(),
   146→                Token::Semicolon => "Semicolon".into(),
   147→                Token::Eof       => "Eof".into(),
   148→                Token::Identifier(s) => format!("Identifier({})", s),
   149→                Token::Integer(n)    => format!("Integer({})", n),
   150→                Token::Float(f)      => format!("Float({})", f),
   151→                Token::String(s)     => format!("String({})", s),
   152→            };
   153→            format!(r#""{}""#, repr)
   154→        })
   155→        .collect();
   156→
   157→    format!(r#"{{"success":true,"tokens":[{}]}}"#, items.join(","))
   158→}
   159→
   160→// ── 내부 구현 ────────────────────────────────
   161→fn run_fv(code: &str) -> String {
   162→    let lexer = match fv_lang::Lexer::new(code) {
   163→        Ok(l) => l,
   164→        Err(e) => return format!(r#"{{"success":false,"error":"Lexer 오류: {}"}}"#, e),
   165→    };
   166→    let tokens = match lexer.tokenize() {
   167→        Ok(t) => t,
   168→        Err(e) => return format!(r#"{{"success":false,"error":"토큰 오류: {}"}}"#, e),
   169→    };
   170→    let parser = match fv_lang::Parser::new(tokens) {
   171→        Ok(p) => p,
   172→        Err(e) => return format!(r#"{{"success":false,"error":"파서 초기화 오류: {}"}}"#, e),
   173→    };
   174→    let ast = match parser.parse() {
   175→        Ok(a) => a,
   176→        Err(e) => return format!(r#"{{"success":false,"error":"파싱 오류: {}"}}"#, e),
   177→    };
   178→    match fv_lang::CodeGenerator::new().generate(&ast) {
   179→        Ok(out) => format!(r#"{{"success":true,"output":{}}}"#, json_str(&out)),
   180→        Err(e)  => format!(r#"{{"success":false,"error":"컴파일 오류: {}"}}"#, e),
   181→    }
   182→}
   183→
   184→fn parse_ast(code: &str) -> String {
   185→    let lexer = match fv_lang::Lexer::new(code) {
   186→        Ok(l) => l,
   187→        Err(e) => return format!(r#"{{"success":false,"error":"{}"}}"#, e),
   188→    };
   189→    let tokens = match lexer.tokenize() {
   190→        Ok(t) => t,
   191→        Err(e) => return format!(r#"{{"success":false,"error":"{}"}}"#, e),
   192→    };
   193→    let parser = match fv_lang::Parser::new(tokens) {
   194→        Ok(p) => p,
   195→        Err(e) => return format!(r#"{{"success":false,"error":"{}"}}"#, e),
   196→    };
   197→    match parser.parse() {
   198→        Ok(ast) => {
   199→            let debug_str = format!("{:#?}", ast);
   200→            format!(r#"{{"success":true,"ast":{}}}"#, json_str(&debug_str))
   201→        }
   202→        Err(e) => format!(r#"{{"success":false,"error":"{}"}}"#, e),
   203→    }
   204→}
   205→
   206→fn json_str(s: &str) -> String {
   207→    let mut out = String::with_capacity(s.len() + 2);
   208→    out.push('"');
   209→    for c in s.chars() {
   210→        match c {
   211→            '\\' => out.push_str("\\\\"),
   212→            '"'  => out.push_str("\\\""),
   213→            '\n' => out.push_str("\\n"),
   214→            '\r' => out.push_str("\\r"),
   215→            '\t' => out.push_str("\\t"),
   216→            '\x00'..='\x1f' => {
   217→                out.push_str(&format!("\\u{:04x}", c as u32));
   218→            }
   219→            _ => out.push(c),
   220→        }
   221→    }
   222→    out.push('"');
   223→    out
   224→}
