// Phase 1 — Lexer 단위 테스트
// fv-lang Lexer의 토큰 타입별 동작 검증

#[cfg(test)]
mod tests {
    use fv_lang::Lexer;
    use fv_lang::lexer::Token;

    // ── 헬퍼 ──────────────────────────────────────
    fn tokenize(src: &str) -> Vec<Token> {
        let lex = Lexer::new(src).expect("Lexer::new 실패");
        let mut toks = lex.tokenize().expect("tokenize 실패");
        // 마지막 Eof 제거
        if toks.last() == Some(&Token::Eof) {
            toks.pop();
        }
        toks
    }

    fn tokenize_err(src: &str) -> String {
        match Lexer::new(src) {
            Err(e) => return e.to_string(),
            Ok(lex) => match lex.tokenize() {
                Err(e) => e.to_string(),
                Ok(_) => panic!("에러를 기대했지만 성공함: {:?}", src),
            },
        }
    }

    // ── 1. 키워드 테스트 ───────────────────────────

