     1→// FV-Lang (Free Value Language)
     2→// A functional-first programming language with strong type inference
     3→//
     4→// This library provides the core compiler infrastructure:
     5→// - Lexer: Tokenization
     6→// - Parser: Abstract Syntax Tree construction
     7→// - Type System: Type inference and checking
     8→// - Code Generator: Compilation to IR/Native code
     9→
    10→pub mod lexer;
    11→pub mod parser;
    12→pub mod ast;
    13→pub mod types;
    14→pub mod symbols;
    15→pub mod type_checker;
    16→pub mod ir;
    17→pub mod codegen;
    18→pub mod value;
    19→pub mod heap;
    20→pub mod stack;
    21→pub mod runtime;
    22→pub mod compiler;
    23→pub mod stdlib;
    24→
    25→pub use lexer::Lexer;
    26→pub use parser::Parser;
    27→pub use ast::Program;
    28→pub use types::Type;
    29→pub use symbols::SymbolTable;
    30→pub use type_checker::{TypeChecker, TypeError};
    31→pub use codegen::CodeGenerator;
    32→pub use value::Value;
    33→pub use heap::Heap;
    34→pub use stack::{Stack, StackFrame};
    35→pub use runtime::{Runtime, RuntimeError};
    36→pub use compiler::{Compiler, CompileError as CompilerError, CompilationResult};
    37→
    38→/// Compile FV-Lang source code to string output
    39→pub fn compile(source: &str) -> Result<String, CompileError> {
    40→    // Lexer: Source → Tokens
    41→    let lexer = Lexer::new(source).map_err(|e| CompileError::LexerError(e.to_string()))?;
    42→    let tokens = lexer.tokenize()?;
    43→
    44→    // Parser: Tokens → AST
    45→    let parser = Parser::new(tokens).map_err(|e| CompileError::ParserError(e.to_string()))?;
    46→    let ast = parser.parse()?;
    47→
    48→    // Type Checker: AST 검증 (오류 시 첫 번째 오류 반환)
    49→    let mut type_checker = TypeChecker::new();
    50→    type_checker.check(&ast)
    51→        .map_err(|errs| CompileError::TypeError(
    52→            errs.into_iter().map(|e| e.to_string()).collect::<Vec<_>>().join(", ")
    53→        ))?;
    54→
    55→    // Code Generator: AST → 출력 코드
    56→    let codegen = CodeGenerator::new();
    57→    let code = codegen.generate(&ast)?;
    58→
    59→    Ok(code)
    60→}
    61→
    62→#[derive(Debug, Clone)]
    63→pub enum CompileError {
    64→    LexerError(String),
    65→    ParserError(String),
    66→    TypeError(String),
    67→    GenerationError(String),
    68→}
    69→
    70→impl std::fmt::Display for CompileError {
    71→    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
    72→        match self {
    73→            CompileError::LexerError(e) => write!(f, "Lexer error: {}", e),
    74→            CompileError::ParserError(e) => write!(f, "Parser error: {}", e),
    75→            CompileError::TypeError(e) => write!(f, "Type error: {}", e),
    76→            CompileError::GenerationError(e) => write!(f, "Generation error: {}", e),
    77→        }
    78→    }
    79→}
    80→
    81→impl std::error::Error for CompileError {}
    82→

