     1→// Parser: Tokens → Abstract Syntax Tree
     2→// Parses FV-Lang token stream into an AST
     3→// Security hardened with recursion depth limits
     4→
     5→use crate::{lexer::Token, ast::*, CompileError};
     6→
     7→// Security limits
     8→const MAX_PARSE_DEPTH: usize = 1000;  // 최대 파싱 깊이
     9→const MAX_TOKENS: usize = 100_000;    // 최대 토큰 수
    10→
    11→pub struct Parser {
    12→    tokens: Vec<Token>,
    13→    pos: usize,
    14→    errors: Vec<CompileError>,  // ✅ 에러 수집
    15→}
    16→
    17→impl Parser {
    18→    /// 토큰 배열 크기 검증과 함께 파서 생성
    19→    pub fn new(tokens: Vec<Token>) -> Result<Self, CompileError> {
    20→        if tokens.len() > MAX_TOKENS {
    21→            return Err(CompileError::ParserError(format!(
    22→                "토큰 수가 너무 많음: {} (최대 {})",
    23→                tokens.len(),
    24→                MAX_TOKENS
    25→            )));
    26→        }
    27→
    28→        Ok(Parser {
    29→            tokens,
    30→            pos: 0,
    31→            errors: Vec::new(),
    32→        })
    33→    }
    34→
    35→    /// 에러 복구: 다음 동기화 포인트까지 스킵
    36→    fn synchronize(&mut self) {
    37→        self.advance();
    38→
    39→        while !self.is_at_end() {
    40→            if self.tokens.get(self.pos.saturating_sub(1)) == Some(&Token::Semicolon) {
    41→                return;
    42→            }
    43→
    44→            match self.peek() {
    45→                Token::Fn | Token::Type | Token::Let | Token::If | Token::Return => return,
    46→                Token::RBrace | Token::Eof => return,
    47→                _ => self.advance(),
    48→            }
    49→        }
    50→    }
    51→
    52→    pub fn parse(mut self) -> Result<Program, CompileError> {
    53→        let mut definitions = Vec::new();
    54→        let mut statements = Vec::new();
    55→
    56→        while !self.is_at_end() {
    57→            match self.peek() {
    58→                Token::Fn => {
    59→                    match self.parse_function() {
    60→                        Ok(Some(def)) => definitions.push(def),
    61→                        Ok(None) => break,
    62→                        Err(_) => { self.synchronize(); }
    63→                    }
    64→                }
    65→                Token::Type => {
    66→                    match self.parse_type_def() {
    67→                        Ok(Some(def)) => definitions.push(def),
    68→                        Ok(None) => break,
    69→                        Err(_) => { self.synchronize(); }
    70→                    }
    71→                }
    72→                Token::Eof => break,
    73→                // 최상위 구문 (let, 표현식 등)
    74→                _ => {
    75→                    match self.parse_statement() {
    76→                        Ok(stmt) => statements.push(stmt),
    77→                        Err(_) => { self.synchronize(); }
    78→                    }
    79→                }
    80→            }
    81→        }
    82→
    83→        Ok(Program { definitions, statements })
    84→    }
    85→
    86→    fn parse_definition(&mut self) -> Result<Option<Definition>, CompileError> {
    87→        match self.peek() {
    88→            Token::Fn => self.parse_function(),
    89→            Token::Type => self.parse_type_def(),
    90→            Token::Eof => Ok(None),
    91→            _ => Err(CompileError::ParserError(
    92→                format!("Expected definition, found {:?}", self.peek()),
    93→            )),
    94→        }
    95→    }
    96→
    97→    fn parse_function(&mut self) -> Result<Option<Definition>, CompileError> {
    98→        self.expect(Token::Fn)?;
    99→
   100→        let name = match self.peek() {
   101→            Token::Identifier(n) => {
   102→                let name = n.clone();
   103→                self.advance();
   104→                name
   105→            }
   106→            _ => return Err(CompileError::ParserError("Expected function name".to_string())),
   107→        };
   108→
   109→        self.expect(Token::LParen)?;
   110→
   111→        let mut params = Vec::new();
   112→        while self.peek() != &Token::RParen {
   113→            if !params.is_empty() {
   114→                self.expect(Token::Comma)?;
   115→            }
   116→
   117→            if let Token::Identifier(param_name) = self.peek() {
   118→                let param = param_name.clone();
   119→                self.advance();
   120→                self.expect(Token::Colon)?;
   121→                let _param_type = self.parse_type()?;
   122→                params.push(param);
   123→            }
   124→        }
   125→
   126→        self.expect(Token::RParen)?;
   127→        self.expect(Token::Arrow)?;
   128→        let _return_type = self.parse_type()?;
   129→
   130→        self.expect(Token::LBrace)?;
   131→        let body = self.parse_block()?;
   132→        self.expect(Token::RBrace)?;
   133→
   134→        Ok(Some(Definition::Function {
   135→            name,
   136→            params,
   137→            body,
   138→        }))
   139→    }
   140→
   141→    fn parse_type_def(&mut self) -> Result<Option<Definition>, CompileError> {
   142→        self.expect(Token::Type)?;
   143→
   144→        if let Token::Identifier(name) = self.peek() {
   145→            let name = name.clone();
   146→            self.advance();
   147→            self.expect(Token::Assign)?;
   148→            let _type_expr = self.parse_type()?;
   149→            self.expect(Token::Semicolon)?;
   150→
   151→            Ok(Some(Definition::TypeDef { name }))
   152→        } else {
   153→            Err(CompileError::ParserError("Expected type name".to_string()))
   154→        }
   155→    }
   156→
   157→    fn parse_block(&mut self) -> Result<Vec<Statement>, CompileError> {
   158→        let mut statements = Vec::new();
   159→
   160→        while self.peek() != &Token::RBrace && !self.is_at_end() {
   161→            statements.push(self.parse_statement()?);
   162→        }
   163→
   164→        Ok(statements)
   165→    }
   166→
   167→    fn parse_statement(&mut self) -> Result<Statement, CompileError> {
   168→        match self.peek() {
   169→            Token::Let => self.parse_let_binding(),
   170→            Token::Return => self.parse_return(),
   171→            Token::If => self.parse_if(),
   172→            Token::Match => self.parse_match(),
   173→            _ => self.parse_expression_statement(),
   174→        }
   175→    }
   176→
   177→    fn parse_let_binding(&mut self) -> Result<Statement, CompileError> {
   178→        self.expect(Token::Let)?;
   179→
   180→        if let Token::Identifier(name) = self.peek() {
   181→            let name = name.clone();
   182→            self.advance();
   183→            self.expect(Token::Assign)?;
   184→            let expr = self.parse_expression()?;
   185→            self.expect(Token::Semicolon)?;
   186→
   187→            Ok(Statement::LetBinding {
   188→                name,
   189→                value: Box::new(expr),
   190→            })
   191→        } else {
   192→            Err(CompileError::ParserError("Expected variable name".to_string()))
   193→        }
   194→    }
   195→
   196→    fn parse_return(&mut self) -> Result<Statement, CompileError> {
   197→        self.expect(Token::Return)?;
   198→        let expr = self.parse_expression()?;
   199→        self.expect(Token::Semicolon)?;
   200→        Ok(Statement::Return(Box::new(expr)))
   201→    }
   202→
   203→    fn parse_if(&mut self) -> Result<Statement, CompileError> {
   204→        self.expect(Token::If)?;
   205→        let condition = Box::new(self.parse_expression()?);
   206→        self.expect(Token::LBrace)?;
   207→        let then_branch = self.parse_block()?;
   208→        self.expect(Token::RBrace)?;
   209→
   210→        let else_branch = if self.peek() == &Token::Else {
   211→            self.advance();
   212→            self.expect(Token::LBrace)?;
   213→            let block = self.parse_block()?;
   214→            self.expect(Token::RBrace)?;
   215→            Some(block)
   216→        } else {
   217→            None
   218→        };
   219→
   220→        Ok(Statement::If {
   221→            condition,
   222→            then_branch,
   223→            else_branch,
   224→        })
   225→    }
   226→
   227→    fn parse_match(&mut self) -> Result<Statement, CompileError> {
   228→        self.expect(Token::Match)?;
   229→        let _expr = Box::new(self.parse_expression()?);
   230→        self.expect(Token::LBrace)?;
   231→
   232→        // Parse match patterns
   233→        while self.peek() != &Token::RBrace && !self.is_at_end() {
   234→            self.expect(Token::Pipe)?;
   235→            let _pattern = match self.peek() {
   236→                Token::Identifier(_) => {
   237→                    self.advance();
   238→                }
   239→                _ => return Err(CompileError::ParserError("Expected pattern".to_string())),
   240→            };
   241→            self.expect(Token::FatArrow)?;
   242→            let _ = self.parse_expression()?;
   243→            self.expect(Token::Comma)?;
   244→        }
   245→
   246→        self.expect(Token::RBrace)?;
   247→        Ok(Statement::Expression(Box::new(Expression::Literal(Literal::Integer(0)))))
   248→    }
   249→
   250→    fn parse_expression_statement(&mut self) -> Result<Statement, CompileError> {
   251→        let expr = self.parse_expression()?;
   252→        if self.peek() == &Token::Semicolon {
   253→            self.advance();
   254→        }
   255→        Ok(Statement::Expression(Box::new(expr)))
   256→    }
   257→
   258→    fn parse_expression(&mut self) -> Result<Expression, CompileError> {
   259→        self.parse_binary_expr(0, 0)
   260→    }
   261→
   262→    fn parse_binary_expr(&mut self, min_prec: i32, depth: usize) -> Result<Expression, CompileError> {
   263→        // ✅ 재귀 깊이 제한 확인
   264→        if depth > MAX_PARSE_DEPTH {
   265→            return Err(CompileError::ParserError(
   266→                format!("파싱 깊이 초과 (최대: {})", MAX_PARSE_DEPTH)
   267→            ));
   268→        }
   269→
   270→        let mut left = self.parse_primary(depth + 1)?;
   271→
   272→        while let Some(prec) = self.get_precedence(self.peek()) {
   273→            if prec < min_prec {
   274→                break;
   275→            }
   276→
   277→            let op = format!("{:?}", self.peek());
   278→            self.advance();
   279→
   280→            let right = self.parse_binary_expr(prec + 1, depth + 1)?;
   281→            left = Expression::BinaryOp {
   282→                op,
   283→                left: Box::new(left),
   284→                right: Box::new(right),
   285→            };
   286→        }
   287→
   288→        Ok(left)
   289→    }
   290→
   291→    fn parse_primary(&mut self, depth: usize) -> Result<Expression, CompileError> {
   292→        // ✅ 깊이 확인
   293→        if depth > MAX_PARSE_DEPTH {
   294→            return Err(CompileError::ParserError(
   295→                format!("파싱 깊이 초과 (최대: {})", MAX_PARSE_DEPTH)
   296→            ));
   297→        }
   298→
   299→        // ✅ 단항 연산자 처리
   300→        match self.peek() {
   301→            Token::Not | Token::Minus => {
   302→                let op = format!("{:?}", self.peek());
   303→                self.advance();
   304→                let operand = self.parse_primary(depth + 1)?;
   305→                return Ok(Expression::UnaryOp {
   306→                    op,
   307→                    operand: Box::new(operand),
   308→                });
   309→            }
   310→            _ => {}
   311→        }
   312→
   313→        match self.peek() {
   314→            Token::Integer(n) => {
   315→                let val = *n;
   316→                self.advance();
   317→                Ok(Expression::Literal(Literal::Integer(val)))
   318→            }
   319→            Token::Float(f) => {
   320→                let val = *f;
   321→                self.advance();
   322→                Ok(Expression::Literal(Literal::Float(val)))
   323→            }
   324→            Token::String(s) => {
   325→                let val = s.clone();
   326→                self.advance();
   327→                Ok(Expression::Literal(Literal::String(val)))
   328→            }
   329→            Token::True => {
   330→                self.advance();
   331→                Ok(Expression::Literal(Literal::Boolean(true)))
   332→            }
   333→            Token::False => {
   334→                self.advance();
   335→                Ok(Expression::Literal(Literal::Boolean(false)))
   336→            }
   337→            Token::Identifier(name) => {
   338→                let name = name.clone();
   339→                self.advance();
   340→
   341→                if self.peek() == &Token::LParen {
   342→                    self.advance();
   343→                    let mut args = Vec::new();
   344→                    while self.peek() != &Token::RParen {
   345→                        args.push(self.parse_binary_expr(0, depth + 1)?);
   346→                        if self.peek() == &Token::Comma {
   347→                            self.advance();
   348→                        }
   349→                    }
   350→                    self.expect(Token::RParen)?;
   351→                    Ok(Expression::FunctionCall {
   352→                        name,
   353→                        args,
   354→                    })
   355→                } else {
   356→                    Ok(Expression::Variable(name))
   357→                }
   358→            }
   359→            Token::LParen => {
   360→                self.advance();
   361→                let expr = self.parse_binary_expr(0, depth + 1)?;
   362→                self.expect(Token::RParen)?;
   363→                Ok(expr)
   364→            }
   365→            Token::If => {
   366→                self.advance();
   367→                let condition = Box::new(self.parse_binary_expr(0, depth + 1)?);
   368→                self.expect(Token::LBrace)?;
   369→                let then_expr = Box::new(self.parse_expression_or_block(depth + 1)?);
   370→                self.expect(Token::RBrace)?;
   371→
   372→                let else_expr = if self.peek() == &Token::Else {
   373→                    self.advance();
   374→                    self.expect(Token::LBrace)?;
   375→                    let expr = Box::new(self.parse_expression_or_block(depth + 1)?);
   376→                    self.expect(Token::RBrace)?;
   377→                    Some(expr)
   378→                } else {
   379→                    None
   380→                };
   381→
   382→                Ok(Expression::IfExpr {
   383→                    condition,
   384→                    then_expr,
   385→                    else_expr,
   386→                })
   387→            }
   388→            _ => Err(CompileError::ParserError(
   389→                format!("Unexpected token in expression: {:?}", self.peek()),
   390→            )),
   391→        }
   392→    }
   393→
   394→    fn parse_expression_or_block(&mut self, depth: usize) -> Result<Expression, CompileError> {
   395→        // 블록 내의 표현식 또는 마지막 문장 파싱
   396→        let mut last_expr = Expression::Literal(Literal::Integer(0));
   397→
   398→        while self.peek() != &Token::RBrace && !self.is_at_end() {
   399→            match self.peek() {
   400→                Token::Return => {
   401→                    self.advance();
   402→                    return self.parse_binary_expr(0, depth);
   403→                }
   404→                Token::Let => {
   405→                    self.advance();
   406→                    if let Token::Identifier(name) = self.peek() {
   407→                        let name = name.clone();
   408→                        self.advance();
   409→                        self.expect(Token::Assign)?;
   410→                        let expr = self.parse_binary_expr(0, depth)?;
   411→                        self.expect(Token::Semicolon)?;
   412→                        last_expr = expr;
   413→                    }
   414→                }
   415→                Token::If => {
   416→                    return self.parse_primary(depth);
   417→                }
   418→                _ => {
   419→                    last_expr = self.parse_binary_expr(0, depth)?;
   420→                    if self.peek() == &Token::Semicolon {
   421→                        self.advance();
   422→                    }
   423→                }
   424→            }
   425→        }
   426→
   427→        Ok(last_expr)
   428→    }
   429→
   430→    fn parse_type(&mut self) -> Result<String, CompileError> {
   431→        match self.peek() {
   432→            Token::Identifier(t) => {
   433→                let type_name = t.clone();
   434→                self.advance();
   435→                Ok(type_name)
   436→            }
   437→            _ => Err(CompileError::ParserError("Expected type".to_string())),
   438→        }
   439→    }
   440→
   441→    fn get_precedence(&self, token: &Token) -> Option<i32> {
   442→        match token {
   443→            Token::Or => Some(1),
   444→            Token::And => Some(2),
   445→            Token::Eq | Token::Ne => Some(3),
   446→            Token::Lt | Token::Le | Token::Gt | Token::Ge => Some(4),
   447→            Token::Plus | Token::Minus => Some(5),
   448→            Token::Star | Token::Slash | Token::Percent => Some(6),
   449→            _ => None,
   450→        }
   451→    }
   452→
   453→    fn peek(&self) -> &Token {
   454→        self.tokens.get(self.pos).unwrap_or(&Token::Eof)
   455→    }
   456→
   457→    fn advance(&mut self) {
   458→        if !self.is_at_end() {
   459→            self.pos += 1;
   460→        }
   461→    }
   462→
   463→    fn is_at_end(&self) -> bool {
   464→        matches!(self.peek(), Token::Eof)
   465→    }
   466→
   467→    fn expect(&mut self, expected: Token) -> Result<(), CompileError> {
   468→        if std::mem::discriminant(self.peek()) == std::mem::discriminant(&expected) {
   469→            self.advance();
   470→            Ok(())
   471→        } else {
   472→            let err = CompileError::ParserError(
   473→                format!("Expected {:?}, found {:?}", expected, self.peek()),
   474→            );
   475→            self.errors.push(err.clone());
   476→            self.synchronize();  // ✅ 동기화 포인트까지 스킵
   477→            Err(err)
   478→        }
   479→    }
   480→
   481→    /// 수집된 모든 에러 반환
   482→    pub fn get_errors(&self) -> Vec<CompileError> {
   483→        self.errors.clone()
   484→    }
