// Phase 2 — Parser 단위 테스트
// fv-lang Parser의 AST 생성 동작 검증

#[cfg(test)]
mod tests {
    use fv_lang::{Lexer, Parser};
    use fv_lang::ast::{Definition, Expression, Literal, Statement};

    // ── 헬퍼 ──────────────────────────────────────

    /// 소스 코드를 파싱해 Program 반환 (실패 시 패닉)
    fn parse(src: &str) -> fv_lang::ast::Program {
        let lex = Lexer::new(src).expect("Lexer::new 실패");
        let tokens = lex.tokenize().expect("tokenize 실패");
        let parser = Parser::new(tokens).expect("Parser::new 실패");
        parser.parse().expect("parse 실패")
    }

    /// 파싱이 에러를 반환해야 하는 경우 에러 메시지 반환
    fn parse_err(src: &str) -> String {
        let lex = Lexer::new(src).expect("Lexer::new 실패");
        let tokens = match lex.tokenize() {
            Ok(t) => t,
            Err(e) => return e.to_string(),
        };
        let parser = match Parser::new(tokens) {
            Ok(p) => p,
            Err(e) => return e.to_string(),
        };
        match parser.parse() {
            Err(e) => e.to_string(),
            // 파서가 에러 복구를 통해 성공을 반환하는 경우도 허용
            Ok(prog) => format!("parse_ok:{} defs, {} stmts",
                prog.definitions.len(), prog.statements.len()),
        }
    }

    /// get_ast_json 래퍼 - JSON 문자열 검증용
    fn ast_json(src: &str) -> String {
        crate::get_ast_json(src)
    }

    // ══════════════════════════════════════════════
    // 1. LetBinding 테스트
    // ══════════════════════════════════════════════

    #[test]
    fn test_let_integer_literal() {
        // let x = 42; → LetBinding { name: "x", value: Literal(Integer(42)) }
        let prog = parse("let x = 42;");
        assert_eq!(prog.statements.len(), 1);
        match &prog.statements[0] {
            Statement::LetBinding { name, value } => {
                assert_eq!(name, "x");
                match value.as_ref() {
                    Expression::Literal(Literal::Integer(n)) => assert_eq!(*n, 42),
                    other => panic!("Integer 리터럴 기대, 실제: {:?}", other),
                }
            }
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    #[test]
    fn test_let_float_literal() {
        // let pi = 3.14;
        let prog = parse("let pi = 3.14;");
        assert_eq!(prog.statements.len(), 1);
        match &prog.statements[0] {
            Statement::LetBinding { name, value } => {
                assert_eq!(name, "pi");
                match value.as_ref() {
                    Expression::Literal(Literal::Float(f)) => {
                        let diff = (f - 3.14_f64).abs();
                        assert!(diff < 1e-9, "3.14 기대, 실제: {}", f);
                    }
                    other => panic!("Float 리터럴 기대, 실제: {:?}", other),
                }
            }
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    #[test]
    fn test_let_string_literal() {
        // let greeting = "hello";
        let prog = parse(r#"let greeting = "hello";"#);
        assert_eq!(prog.statements.len(), 1);
        match &prog.statements[0] {
            Statement::LetBinding { name, value } => {
                assert_eq!(name, "greeting");
                match value.as_ref() {
                    Expression::Literal(Literal::String(s)) => assert_eq!(s, "hello"),
                    other => panic!("String 리터럴 기대, 실제: {:?}", other),
                }
            }
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    #[test]
    fn test_let_bool_true() {
        // let flag = true;
        let prog = parse("let flag = true;");
        match &prog.statements[0] {
            Statement::LetBinding { name, value } => {
                assert_eq!(name, "flag");
                match value.as_ref() {
                    Expression::Literal(Literal::Boolean(b)) => assert!(*b),
                    other => panic!("Boolean true 기대, 실제: {:?}", other),
                }
            }
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    #[test]
    fn test_let_bool_false() {
        // let done = false;
        let prog = parse("let done = false;");
        match &prog.statements[0] {
            Statement::LetBinding { name, value } => {
                assert_eq!(name, "done");
                match value.as_ref() {
                    Expression::Literal(Literal::Boolean(b)) => assert!(!b),
                    other => panic!("Boolean false 기대, 실제: {:?}", other),
                }
            }
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    #[test]
    fn test_let_variable_reference() {
        // let y = x; (변수 참조)
        let prog = parse("let y = x;");
        match &prog.statements[0] {
            Statement::LetBinding { name, value } => {
                assert_eq!(name, "y");
                match value.as_ref() {
                    Expression::Variable(var) => assert_eq!(var, "x"),
                    other => panic!("Variable 기대, 실제: {:?}", other),
                }
            }
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    // ══════════════════════════════════════════════
    // 2. BinaryOp 산술 연산 테스트
    // ══════════════════════════════════════════════

    #[test]
    fn test_binary_add() {
        // let r = 1 + 2;
        let prog = parse("let r = 1 + 2;");
        match &prog.statements[0] {
            Statement::LetBinding { value, .. } => {
                match value.as_ref() {
                    Expression::BinaryOp { op, left, right } => {
                        assert!(op.contains("Plus"), "op에 'Plus' 포함 기대: {}", op);
                        matches!(left.as_ref(), Expression::Literal(Literal::Integer(1)));
                        matches!(right.as_ref(), Expression::Literal(Literal::Integer(2)));
                    }
                    other => panic!("BinaryOp 기대, 실제: {:?}", other),
                }
            }
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    #[test]
    fn test_binary_subtract() {
        // let r = 10 - 3;
        let prog = parse("let r = 10 - 3;");
        match &prog.statements[0] {
            Statement::LetBinding { value, .. } => match value.as_ref() {
                Expression::BinaryOp { op, .. } => {
                    assert!(op.contains("Minus"), "op에 'Minus' 포함 기대: {}", op);
                }
                other => panic!("BinaryOp 기대, 실제: {:?}", other),
            },
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    #[test]
    fn test_binary_multiply() {
        // let r = 3 * 4;
        let prog = parse("let r = 3 * 4;");
        match &prog.statements[0] {
            Statement::LetBinding { value, .. } => match value.as_ref() {
                Expression::BinaryOp { op, .. } => {
                    assert!(op.contains("Star"), "op에 'Star' 포함 기대: {}", op);
                }
                other => panic!("BinaryOp 기대, 실제: {:?}", other),
            },
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    #[test]
    fn test_binary_divide() {
        // let r = 10 / 2;
        let prog = parse("let r = 10 / 2;");
        match &prog.statements[0] {
            Statement::LetBinding { value, .. } => match value.as_ref() {
                Expression::BinaryOp { op, .. } => {
                    assert!(op.contains("Slash"), "op에 'Slash' 포함 기대: {}", op);
                }
                other => panic!("BinaryOp 기대, 실제: {:?}", other),
            },
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    #[test]
    fn test_binary_modulo() {
        // let r = 7 % 3;
        let prog = parse("let r = 7 % 3;");
        match &prog.statements[0] {
            Statement::LetBinding { value, .. } => match value.as_ref() {
                Expression::BinaryOp { op, .. } => {
                    assert!(op.contains("Percent"), "op에 'Percent' 포함 기대: {}", op);
                }
                other => panic!("BinaryOp 기대, 실제: {:?}", other),
            },
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    // ══════════════════════════════════════════════
    // 3. BinaryOp 비교/논리 연산 테스트
    // ══════════════════════════════════════════════

    #[test]
    fn test_binary_equality() {
        // let r = x == y;
        let prog = parse("let r = x == y;");
        match &prog.statements[0] {
            Statement::LetBinding { value, .. } => match value.as_ref() {
                Expression::BinaryOp { op, .. } => {
                    assert!(op.contains("Eq"), "op에 'Eq' 포함 기대: {}", op);
                }
                other => panic!("BinaryOp 기대, 실제: {:?}", other),
            },
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    #[test]
    fn test_binary_less_than() {
        // let r = a < b;
        let prog = parse("let r = a < b;");
        match &prog.statements[0] {
            Statement::LetBinding { value, .. } => match value.as_ref() {
                Expression::BinaryOp { op, .. } => {
                    assert!(op.contains("Lt"), "op에 'Lt' 포함 기대: {}", op);
                }
                other => panic!("BinaryOp 기대, 실제: {:?}", other),
            },
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    #[test]
    fn test_binary_logical_and() {
        // let r = a && b;
        let prog = parse("let r = a && b;");
        match &prog.statements[0] {
            Statement::LetBinding { value, .. } => match value.as_ref() {
                Expression::BinaryOp { op, .. } => {
                    assert!(op.contains("And"), "op에 'And' 포함 기대: {}", op);
                }
                other => panic!("BinaryOp 기대, 실제: {:?}", other),
            },
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    // ══════════════════════════════════════════════
    // 4. UnaryOp 테스트
    // ══════════════════════════════════════════════

    #[test]
    fn test_unary_not() {
        // let r = !flag;
        let prog = parse("let r = !flag;");
        match &prog.statements[0] {
            Statement::LetBinding { value, .. } => match value.as_ref() {
                Expression::UnaryOp { op, operand } => {
                    assert!(op.contains("Not"), "op에 'Not' 포함 기대: {}", op);
                    match operand.as_ref() {
                        Expression::Variable(v) => assert_eq!(v, "flag"),
                        other => panic!("Variable 기대, 실제: {:?}", other),
                    }
                }
                other => panic!("UnaryOp 기대, 실제: {:?}", other),
            },
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    #[test]
    fn test_unary_negate() {
        // let r = -42;
        let prog = parse("let r = -42;");
        match &prog.statements[0] {
            Statement::LetBinding { value, .. } => match value.as_ref() {
                Expression::UnaryOp { op, operand } => {
                    assert!(op.contains("Minus"), "op에 'Minus' 포함 기대: {}", op);
                    match operand.as_ref() {
                        Expression::Literal(Literal::Integer(n)) => assert_eq!(*n, 42),
                        other => panic!("Integer 기대, 실제: {:?}", other),
                    }
                }
                other => panic!("UnaryOp 기대, 실제: {:?}", other),
            },
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    // ══════════════════════════════════════════════
    // 5. 중첩 표현식 테스트
    // ══════════════════════════════════════════════

    #[test]
    fn test_nested_arithmetic() {
        // let r = (1 + 2) * 3; — 파서는 괄호로 연산자 우선순위 재정의 허용
        let prog = parse("let r = (1 + 2) * 3;");
        match &prog.statements[0] {
            Statement::LetBinding { value, .. } => {
                // 최상위는 BinaryOp(Star) 이어야 함
                match value.as_ref() {
                    Expression::BinaryOp { op, left, .. } => {
                        assert!(op.contains("Star"), "최상위는 곱셈: {}", op);
                        // left는 1+2
                        match left.as_ref() {
                            Expression::BinaryOp { op: inner_op, .. } => {
                                assert!(inner_op.contains("Plus"), "내부는 덧셈: {}", inner_op);
                            }
                            other => panic!("내부 BinaryOp 기대, 실제: {:?}", other),
                        }
                    }
                    other => panic!("BinaryOp 기대, 실제: {:?}", other),
                }
            }
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    #[test]
    fn test_operator_precedence_add_mul() {
        // 1 + 2 * 3 → BinaryOp(Plus, 1, BinaryOp(Star, 2, 3))
        // (곱셈이 덧셈보다 높은 우선순위)
        let prog = parse("let r = 1 + 2 * 3;");
        match &prog.statements[0] {
            Statement::LetBinding { value, .. } => match value.as_ref() {
                Expression::BinaryOp { op, right, .. } => {
                    assert!(op.contains("Plus"), "최상위는 덧셈: {}", op);
                    match right.as_ref() {
                        Expression::BinaryOp { op: rhs_op, .. } => {
                            assert!(rhs_op.contains("Star"), "우측은 곱셈: {}", rhs_op);
                        }
                        other => panic!("우측 BinaryOp(Star) 기대, 실제: {:?}", other),
                    }
                }
                other => panic!("BinaryOp 기대, 실제: {:?}", other),
            },
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    // ══════════════════════════════════════════════
    // 6. FunctionCall 테스트
    // ══════════════════════════════════════════════

    #[test]
    fn test_function_call_no_args() {
        // let r = greet();
        let prog = parse("let r = greet();");
        match &prog.statements[0] {
            Statement::LetBinding { value, .. } => match value.as_ref() {
                Expression::FunctionCall { name, args } => {
                    assert_eq!(name, "greet");
                    assert!(args.is_empty(), "인자 없음 기대");
                }
                other => panic!("FunctionCall 기대, 실제: {:?}", other),
            },
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    #[test]
    fn test_function_call_one_arg() {
        // let r = double(x);
        let prog = parse("let r = double(x);");
        match &prog.statements[0] {
            Statement::LetBinding { value, .. } => match value.as_ref() {
                Expression::FunctionCall { name, args } => {
                    assert_eq!(name, "double");
                    assert_eq!(args.len(), 1);
                    match &args[0] {
                        Expression::Variable(v) => assert_eq!(v, "x"),
                        other => panic!("Variable 기대, 실제: {:?}", other),
                    }
                }
                other => panic!("FunctionCall 기대, 실제: {:?}", other),
            },
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    #[test]
    fn test_function_call_two_args() {
        // let r = add(1, 2);
        let prog = parse("let r = add(1, 2);");
        match &prog.statements[0] {
            Statement::LetBinding { value, .. } => match value.as_ref() {
                Expression::FunctionCall { name, args } => {
                    assert_eq!(name, "add");
                    assert_eq!(args.len(), 2, "인자 2개 기대");
                    match &args[0] {
                        Expression::Literal(Literal::Integer(1)) => {}
                        other => panic!("첫 번째 인자 1 기대, 실제: {:?}", other),
                    }
                    match &args[1] {
                        Expression::Literal(Literal::Integer(2)) => {}
                        other => panic!("두 번째 인자 2 기대, 실제: {:?}", other),
                    }
                }
                other => panic!("FunctionCall 기대, 실제: {:?}", other),
            },
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    #[test]
    fn test_function_call_expression_arg() {
        // let r = square(a + b);
        let prog = parse("let r = square(a + b);");
        match &prog.statements[0] {
            Statement::LetBinding { value, .. } => match value.as_ref() {
                Expression::FunctionCall { name, args } => {
                    assert_eq!(name, "square");
                    assert_eq!(args.len(), 1);
                    match &args[0] {
                        Expression::BinaryOp { op, .. } => {
                            assert!(op.contains("Plus"), "인자가 덧셈: {}", op);
                        }
                        other => panic!("BinaryOp 인자 기대, 실제: {:?}", other),
                    }
                }
                other => panic!("FunctionCall 기대, 실제: {:?}", other),
            },
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    // ══════════════════════════════════════════════
    // 7. IfExpr (표현식 형태) 테스트
    // ══════════════════════════════════════════════

    #[test]
    fn test_if_expr_with_else() {
        // let r = if cond { 1 } else { 0 };
        let prog = parse("let r = if cond { 1 } else { 0 };");
        match &prog.statements[0] {
            Statement::LetBinding { value, .. } => match value.as_ref() {
                Expression::IfExpr { condition, then_expr, else_expr } => {
                    match condition.as_ref() {
                        Expression::Variable(v) => assert_eq!(v, "cond"),
                        other => panic!("조건 Variable 기대, 실제: {:?}", other),
                    }
                    match then_expr.as_ref() {
                        Expression::Literal(Literal::Integer(1)) => {}
                        other => panic!("then에 1 기대, 실제: {:?}", other),
                    }
                    assert!(else_expr.is_some(), "else 분기 있어야 함");
                    match else_expr.as_ref().unwrap().as_ref() {
                        Expression::Literal(Literal::Integer(0)) => {}
                        other => panic!("else에 0 기대, 실제: {:?}", other),
                    }
                }
                other => panic!("IfExpr 기대, 실제: {:?}", other),
            },
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    #[test]
    fn test_if_expr_without_else() {
        // let r = if flag { 42 };
        let prog = parse("let r = if flag { 42 };");
        match &prog.statements[0] {
            Statement::LetBinding { value, .. } => match value.as_ref() {
                Expression::IfExpr { else_expr, .. } => {
                    assert!(else_expr.is_none(), "else 없어야 함");
                }
                other => panic!("IfExpr 기대, 실제: {:?}", other),
            },
            other => panic!("LetBinding 기대, 실제: {:?}", other),
        }
    }

    // ══════════════════════════════════════════════
    // 8. If Statement 테스트
    // ══════════════════════════════════════════════

    #[test]
    fn test_if_statement_with_else() {
        // if x { let a = 1; } else { let b = 2; }
        let prog = parse("if x { let a = 1; } else { let b = 2; }");
        assert_eq!(prog.statements.len(), 1);
        match &prog.statements[0] {
            Statement::If { condition, then_branch, else_branch } => {
                match condition.as_ref() {
                    Expression::Variable(v) => assert_eq!(v, "x"),
                    other => panic!("Variable 기대, 실제: {:?}", other),
                }
                assert_eq!(then_branch.len(), 1, "then 블록 1개 문장 기대");
                assert!(else_branch.is_some(), "else 분기 있어야 함");
                assert_eq!(else_branch.as_ref().unwrap().len(), 1, "else 블록 1개 문장 기대");
            }
            other => panic!("If Statement 기대, 실제: {:?}", other),
        }
    }

    #[test]
    fn test_if_statement_without_else() {
        // if done { let r = 0; }
        let prog = parse("if done { let r = 0; }");
        match &prog.statements[0] {
            Statement::If { else_branch, .. } => {
                assert!(else_branch.is_none(), "else 없어야 함");
            }
            other => panic!("If Statement 기대, 실제: {:?}", other),
        }
    }

    // ══════════════════════════════════════════════
    // 9. Function Definition 테스트
    // ══════════════════════════════════════════════

    #[test]
    fn test_fn_definition_no_params() {
        // fn hello() -> Int { let r = 0; return r; }
        let prog = parse("fn hello() -> Int { let r = 0; return r; }");
        assert_eq!(prog.definitions.len(), 1);
        match &prog.definitions[0] {
            Definition::Function { name, params, body } => {
                assert_eq!(name, "hello");
                assert!(params.is_empty(), "파라미터 없음 기대");
                assert_eq!(body.len(), 2, "본문 2개 문장 기대");
            }
            other => panic!("Function Definition 기대, 실제: {:?}", other),
        }
    }

    #[test]
    fn test_fn_definition_one_param() {
        // fn double(x: Int) -> Int { return x; }
        let prog = parse("fn double(x: Int) -> Int { return x; }");
        match &prog.definitions[0] {
            Definition::Function { name, params, body } => {
                assert_eq!(name, "double");
                assert_eq!(params.len(), 1, "파라미터 1개 기대");
                assert_eq!(params[0], "x");
                assert_eq!(body.len(), 1);
            }
            other => panic!("Function Definition 기대, 실제: {:?}", other),
        }
    }

    #[test]
    fn test_fn_definition_two_params() {
        // fn add(a: Int, b: Int) -> Int { return a; }
        let prog = parse("fn add(a: Int, b: Int) -> Int { return a; }");
        match &prog.definitions[0] {
            Definition::Function { name, params, .. } => {
                assert_eq!(name, "add");
                assert_eq!(params.len(), 2, "파라미터 2개 기대");
                assert_eq!(params[0], "a");
                assert_eq!(params[1], "b");
            }
            other => panic!("Function Definition 기대, 실제: {:?}", other),
        }
    }

    // ══════════════════════════════════════════════
    // 10. Return Statement 테스트
    // ══════════════════════════════════════════════

    #[test]
    fn test_return_integer() {
        // fn f() -> Int { return 99; }
        let prog = parse("fn f() -> Int { return 99; }");
        match &prog.definitions[0] {
            Definition::Function { body, .. } => {
                match &body[0] {
                    Statement::Return(expr) => match expr.as_ref() {
                        Expression::Literal(Literal::Integer(n)) => assert_eq!(*n, 99),
                        other => panic!("Integer 99 기대, 실제: {:?}", other),
                    },
                    other => panic!("Return 기대, 실제: {:?}", other),
                }
            }
            other => panic!("Function 기대, 실제: {:?}", other),
        }
    }

    #[test]
    fn test_return_expression() {
        // fn f() -> Int { return a + b; }
        let prog = parse("fn f() -> Int { return a + b; }");
        match &prog.definitions[0] {
            Definition::Function { body, .. } => {
                match &body[0] {
                    Statement::Return(expr) => match expr.as_ref() {
                        Expression::BinaryOp { op, .. } => {
                            assert!(op.contains("Plus"), "덧셈 기대: {}", op);
                        }
                        other => panic!("BinaryOp 기대, 실제: {:?}", other),
                    },
                    other => panic!("Return 기대, 실제: {:?}", other),
                }
            }
            other => panic!("Function 기대, 실제: {:?}", other),
        }
    }

    // ══════════════════════════════════════════════
    // 11. 여러 구문 순서 테스트
    // ══════════════════════════════════════════════

    #[test]
    fn test_multiple_let_statements() {
        let prog = parse("let a = 1;\nlet b = 2;\nlet c = 3;");
        assert_eq!(prog.statements.len(), 3, "3개 let 구문 기대");
        let names: Vec<&str> = prog.statements.iter().map(|s| {
            match s {
                Statement::LetBinding { name, .. } => name.as_str(),
                _ => panic!("LetBinding 기대"),
            }
        }).collect();
        assert_eq!(names, vec!["a", "b", "c"]);
    }

    #[test]
    fn test_fn_and_statements_separated() {
        // 함수 정의 + 최상위 구문이 분리됨
        let prog = parse("fn greet() -> Int { return 1; }\nlet x = 42;");
        assert_eq!(prog.definitions.len(), 1, "함수 1개 기대");
        assert_eq!(prog.statements.len(), 1, "최상위 구문 1개 기대");
    }

    // ══════════════════════════════════════════════
    // 12. get_ast_json API 테스트
    // ══════════════════════════════════════════════

    #[test]
    fn test_ast_json_success_format() {
        let json = ast_json("let x = 1;");
        assert!(json.contains("\"success\":true"), "success:true 기대: {}", json);
        assert!(json.contains("\"ast\":"), "ast 필드 기대: {}", json);
    }

    #[test]
    fn test_ast_json_contains_let_binding() {
        let json = ast_json("let answer = 42;");
        assert!(json.contains("success"), "success 필드 기대: {}", json);
        // AST 디버그 출력에 LetBinding 및 Integer 포함 확인
        assert!(json.contains("LetBinding") || json.contains("answer"),
            "let 바인딩 관련 내용 기대: {}", json);
    }

    #[test]
    fn test_ast_json_fn_definition() {
        let json = ast_json("fn add(a: Int, b: Int) -> Int { return a; }");
        assert!(json.contains("\"success\":true"), "success:true 기대: {}", json);
        assert!(json.contains("add"), "함수명 'add' 기대: {}", json);
    }

    #[test]
    fn test_ast_json_if_expr() {
        let json = ast_json("let r = if x { 1 } else { 0 };");
        assert!(json.contains("\"success\":true"), "success:true 기대: {}", json);
        assert!(json.contains("IfExpr") || json.contains("if"),
            "IfExpr 포함 기대: {}", json);
    }

    #[test]
    fn test_ast_json_empty_program() {
        let json = ast_json("");
        // 빈 프로그램은 성공적으로 파싱됨 (definitions/statements 모두 비어있음)
        assert!(json.contains("\"success\":true"), "빈 코드도 성공 기대: {}", json);
    }

    #[test]
    fn test_ast_json_error_on_invalid_syntax() {
        // "let =" 는 변수명 없이 할당 → 파서 에러
        let json = ast_json("let = 42;");
        // 에러이거나 (success:false), 또는 파서가 복구하여 빈 결과를 반환할 수 있음
        // 두 경우 모두 허용 — 중요한 건 JSON 형식이 유효한 것
        assert!(json.contains("success"), "success 필드 기대: {}", json);
    }

    // ══════════════════════════════════════════════
    // 13. TypeDef 테스트
    // ══════════════════════════════════════════════

    #[test]
    fn test_type_def() {
        // type MyInt = Int;
        let prog = parse("type MyInt = Int;");
        assert_eq!(prog.definitions.len(), 1, "TypeDef 1개 기대");
        match &prog.definitions[0] {
            Definition::TypeDef { name } => {
                assert_eq!(name, "MyInt", "타입명 'MyInt' 기대");
            }
            other => panic!("TypeDef 기대, 실제: {:?}", other),
        }
    }

    // ══════════════════════════════════════════════
    // 14. Expression Statement 테스트
    // ══════════════════════════════════════════════

    #[test]
    fn test_expression_statement_function_call() {
        // 최상위 함수 호출 (세미콜론 선택적)
        let prog = parse("greet()");
        assert_eq!(prog.statements.len(), 1);
        match &prog.statements[0] {
            Statement::Expression(expr) => match expr.as_ref() {
                Expression::FunctionCall { name, .. } => assert_eq!(name, "greet"),
                other => panic!("FunctionCall 기대, 실제: {:?}", other),
            },
            other => panic!("Expression Statement 기대, 실제: {:?}", other),
        }
    }

    #[test]
    fn test_expression_statement_literal() {
        // 단독 리터럴도 표현식 문장으로 파싱됨
        let prog = parse("42");
        assert_eq!(prog.statements.len(), 1);
        match &prog.statements[0] {
            Statement::Expression(expr) => match expr.as_ref() {
                Expression::Literal(Literal::Integer(n)) => assert_eq!(*n, 42),
                other => panic!("Integer 42 기대, 실제: {:?}", other),
            },
            other => panic!("Expression Statement 기대, 실제: {:?}", other),
        }
    }
}

