/// 파싱이 에러를 반환해야 하는 경우 에러 메시지 반환
fn parse_err(src: &str) -> String {
    let lex = Lexer::new(src).expect("Lexer::new 실패");
    let tokens = match lex.tokenize() {
        Ok(t) => t,
        Err(e) => return e.to_string(),
    };
    let parser = match Parser::new(tokens) {
        Ok(p) => p,
        Err(e) => return e.to_string(),
    };
    match parser.parse() {
        Err(e) => e.to_string(),
        // 파서가 에러 복구를 통해 성공을 반환하는 경우도 허용
        Ok(prog) => format!("parse_ok:{} defs, {} stmts",
            prog.definitions.len(), prog.statements.len()),
    }
}

